"A Model Context Protocol server gives a coding agent extra tools: files, the web, a browser, GitHub and the like. This only reaches the agents that sign in through their own command-line tool in Termux (Claude Code, Gemini CLI, Codex, Copilot CLI, Cursor CLI, OpenCode) — an agent used only with an API key cannot use one here.": "Server Model Context Protocol memberi agen koding alat tambahan: file, web, browser, GitHub, dan sejenisnya. Ini hanya berlaku untuk agen yang login lewat alat command-line mereka sendiri di Termux (Claude Code, Gemini CLI, Codex, Copilot CLI, Cursor CLI, OpenCode) — agen yang hanya memakai kunci API tidak dapat menggunakannya di sini.",
