"A patch bundle asked the patcher for something this build of the app does not have, so it was made for a different Morphe version. Update the source in Sources; if it still happens, report it with the log.": "Paket patch meminta sesuatu dari patcher yang tidak dimiliki versi aplikasi ini, jadi paket itu dibuat untuk versi Morphe yang berbeda. Perbarui sumber di Sumber; jika masih terjadi, laporkan beserta lognya.",
"A patch could not be applied. This usually means the patch does not fit this version of the app. Check the details below and the log.": "Sebuah patch tidak dapat diterapkan. Biasanya ini berarti patch tidak cocok dengan versi aplikasi ini. Periksa detail di bawah dan lognya.",
"A patch source decides what ends up inside your patched apps. Only add sources you trust. It is downloaded now and listed under Sources.": "Sumber patch menentukan apa yang masuk ke aplikasi hasil patch Anda. Tambahkan hanya sumber yang Anda percaya. Sumber diunduh sekarang dan ditampilkan di Sumber.",
"A path exclusion keeps one file or folder, and everything inside it, out of the tools you pick.": "Pengecualian jalur menjauhkan satu berkas atau folder, beserta seluruh isinya, dari alat yang Anda pilih.",
"A persistent Shizuku shell: cd and exports stick. Type exit or tap Exit Rish to leave.": "Shell Shizuku persisten: cd dan export tetap berlaku. Ketik exit atau ketuk Keluar Rish untuk keluar.",
"A phone cannot answer after a reboot, so the sheet says what to expect instead; if nothing happens within ten seconds it says so and shows what the command printed. Recovery and Bootloader land on screens with their own buttons: Reboot system now (recovery) or START (bootloader) brings Android back.": "Ponsel tidak bisa menjawab setelah dimulai ulang, jadi lembar ini memberi tahu apa yang diharapkan; jika tidak terjadi apa-apa dalam sepuluh detik, lembar mengatakannya dan menampilkan keluaran perintah. Recovery dan Bootloader membuka layar dengan tombolnya sendiri: Reboot system now (recovery) atau START (bootloader) mengembalikan Android.",
"A phone without zram, or one whose shell may not read the counters, shows Not available with the reason. The numbers are a snapshot; they move as apps run.": "Ponsel tanpa zram, atau yang shell-nya tidak boleh membaca penghitung, menampilkan Tidak tersedia beserta alasannya. Angka-angka ini adalah potret sesaat; berubah saat aplikasi berjalan.",
"A remote address, SSE": "Alamat jarak jauh, SSE",
"A remote address, streamable HTTP": "Alamat jarak jauh, HTTP streamable",
"A repository: the app will look for its catalog (index-v2.json or index-v1.jar).": "Repositori: aplikasi akan mencari katalognya (index-v2.json atau index-v1.jar).",
"A row": "Satu baris",
"A saturated theme that uses a wide range of colors": "Tema berwarna jenuh yang memakai beragam warna",
"A search is still running": "Pencarian masih berjalan",
"A segment exclusion matches a name segment, like \"DCIM/Camera\", wherever it is.": "Pengecualian segmen cocok dengan segmen nama, seperti “DCIM/Camera”, di mana pun letaknya.",
"A setting that is on or off": "Pengaturan yang aktif atau nonaktif",
"A setting without a description": "Pengaturan tanpa deskripsi",
"A sheet with every action for that app: settings, launch, force stop, enable or disable, uninstall, suspend, permissions, activities. Choose which ones it lists in the Action Button card above.": "Lembar berisi semua tindakan untuk aplikasi itu: pengaturan, luncurkan, paksa berhenti, aktifkan atau nonaktifkan, uninstal, tangguhkan, izin, activity. Pilih mana yang ditampilkan di kartu Tombol Aksi di atas.",
"A short tick you feel when you tap": "Ketukan singkat yang terasa saat Anda mengetuk",
"A short vibration for every button, tab, switch and list row you tap. On by default. It is only the app's own tick: the phone's own touch feedback setting is not changed.": "Getaran singkat untuk setiap tombol, tab, sakelar, dan baris daftar yang Anda ketuk. Aktif secara default. Ini hanya ketukan milik aplikasi: pengaturan umpan balik sentuh ponsel tidak diubah.",
"A small knowledge graph the agent can read and write between turns.": "Graf pengetahuan kecil yang bisa dibaca dan ditulis agen di antara giliran percakapan.",
"A source is a bundle of patches. Turn a source off to keep it without using it: a source that is off is not loaded. More sources are in the Community tab.": "Sumber adalah kumpulan patch. Matikan sumber untuk menyimpannya tanpa menggunakannya: sumber yang mati tidak dimuat. Sumber lainnya ada di tab Komunitas.",
"A strong accent on a plain grey background.": "Aksen kuat di atas latar abu-abu polos.",
"A strong accent that stands out against no background tint": "Aksen kuat yang menonjol tanpa semburat warna pada latar belakang",
"A tab needs a name": "Tab membutuhkan nama",
"A tab on the bottom bar": "Tab di bilah bawah",
"A value can't contain a carriage return (use plain line breaks)": "Nilai tidak boleh berisi carriage return (gunakan baris baru biasa)",
"A value can't contain control characters": "Nilai tidak boleh berisi karakter kontrol",
"A value with several lines.": "Nilai dengan beberapa baris.",
"A web address or URI.": "Alamat web atau URI.",
"A whole number.": "Bilangan bulat.",
"A working mode (ADB, Shizuku or root) is ready. Grant all remaining permissions with it now? The app restarts afterwards.": "Mode kerja (ADB, Shizuku, atau root) sudah siap. Berikan semua izin yang tersisa dengannya sekarang? Aplikasi akan dimulai ulang setelahnya.",
"A wrong value can make the device misbehave. Delete takes the setting away so the system falls back to its default.": "Nilai yang salah dapat membuat perangkat bermasalah. Hapus akan menghilangkan pengaturan ini sehingga sistem kembali ke nilai default-nya.",
