"Adaptive brightness (1 on, 0 off)": "Kecerahan adaptif (1 aktif, 0 nonaktif)",
"Adaptive brightness adjustment (-1 to 1)": "Penyesuaian kecerahan adaptif (-1 sampai 1)",
"Adaptive brightness bias": "Geser kecerahan",
"Adaptive brightness is off, so this has no effect until you turn it on.": "Kecerahan adaptif nonaktif, jadi ini tidak berpengaruh sampai kamu mengaktifkannya.",
"Adaptive brightness picks the screen brightness from the light sensor. This value (Android calls it screen_auto_brightness_adj, from −1 to 1) shifts every choice darker or brighter: 0 is neutral, +0.5 noticeably brighter, −0.5 noticeably darker. It is the same thing the brightness slider changes while adaptive brightness is on.": "Kecerahan adaptif memilih kecerahan layar dari sensor cahaya. Nilai ini (Android menyebutnya screen_auto_brightness_adj, dari −1 sampai 1) menggeser setiap pilihan ke lebih gelap atau lebih terang: 0 netral, +0,5 jelas lebih terang, −0,5 jelas lebih gelap. Ini sama dengan yang diubah penggeser kecerahan saat kecerahan adaptif aktif.",
