"Address (for a remote server)": "Alamat (untuk server jarak jauh)",
"Adds a name and a value to one of the settings tables": "Menambahkan nama dan nilai ke salah satu tabel pengaturan",
"Adult filter: adult content": "Filter dewasa: konten dewasa",
"Advanced": "Lanjutan",
"Advanced mode: choose the patches. App-specific patches and universal patches are listed separately.": "Mode lanjutan: pilih patch. Patch khusus aplikasi dan patch universal ditampilkan terpisah.",
"Advertisement data": "Data iklan",
"Affected paths": "Jalur yang terpengaruh",
"Affected tools": "Alat yang terpengaruh",
"After a successful install, ask whether to delete the installer file (it goes to a hidden folder first, with an Undo)": "Setelah instalasi berhasil, tanyakan apakah file penginstal dihapus (dipindahkan dulu ke folder tersembunyi, dengan Urungkan)",
"After a test, the fastest service comes first. Off keeps the list in its usual order.": "Setelah tes, layanan tercepat tampil lebih dulu. Nonaktif menjaga daftar tetap dalam urutan biasa.",
"Agent websites": "Situs web agen",
"Agent when the app opens": "Agen saat aplikasi dibuka",
"Agents act through four kinds of steps: run a command, read a file, write a file, or edit part of a file. Before a command runs or a file changes you see exactly what, and choose Run (or Apply), Skip, or Always allow for the rest of the chat. Reading files in the current folder needs no OK.": "Agen bertindak lewat empat jenis langkah: menjalankan perintah, membaca file, menulis file, atau mengedit sebagian file. Sebelum perintah dijalankan atau file diubah, Anda melihat persis apa yang akan terjadi, lalu memilih Jalankan (atau Terapkan), Lewati, atau Selalu izinkan untuk sisa chat ini. Membaca file di folder saat ini tidak perlu persetujuan.",
"Agents can be wrong. Read what they want to run, especially with Working mode or Root, where a command can remove apps or change settings.": "Agen bisa salah. Baca apa yang ingin mereka jalankan, terutama dengan Mode kerja atau Root, karena dengan keduanya satu perintah bisa menghapus aplikasi atau mengubah pengaturan.",
"Agents only see what you send and what their steps return; keys and tokens in output are hidden from them.": "Agen hanya melihat apa yang Anda kirim dan apa yang dihasilkan langkah-langkahnya; kunci dan token di output disembunyikan dari agen.",
"Agents to add it to": "Agen tujuan penambahan",
"Airplane mode": "Mode pesawat",
"Airplane mode off": "Mode pesawat nonaktif",
"Airplane mode on": "Mode pesawat aktif",
