"All": "Semua",
"All ADB connections are dropped. Your phone will ask \"Allow debugging?\" again, and Wireless Debugging must be paired again.": "Semua koneksi ADB diputus. Ponsel akan menanyakan “Izinkan debugging?” lagi, dan Debugging nirkabel harus di-pairing ulang.",
