"Also restore app data (replaces its current data)": "Pulihkan juga data aplikasi (menggantikan data saat ini)",
"Also show only (combine as many as you like):": "Persempit dengan (gabungkan sebanyak yang Anda mau):",
"Also sources ~/.bashrc, so aliases and functions from your own Termux shell work here too. Turn off if yours does something unexpected for a non-interactive shell.": "Juga memuat ~/.bashrc, sehingga alias dan fungsi dari shell Termux Anda sendiri juga berfungsi di sini. Nonaktifkan jika file Anda melakukan hal yang tidak terduga pada shell non-interaktif.",
"Also target APK files that match the installed version. Disable to only remove older versions.": "Sasar juga berkas APK yang cocok dengan versi terpasang. Matikan untuk hanya menghapus versi yang lebih lama.",
"Also writes the pure black overlay with root.": "Juga menulis overlay hitam pekat dengan Root.",
