"An app exclusion keeps one app out of the tools you pick (AppCleaner leaves its data alone, CorpseFinder does not call its folders remnants).": "Pengecualian aplikasi menjauhkan satu aplikasi dari alat yang Anda pilih (AppCleaner tidak menyentuh datanya, CorpseFinder tidak menganggap foldernya sisa).",
