"An excluded file, folder or app is skipped by the tools you choose, and nothing in an excluded folder is deleted. Exclude from a scan result with the Exclude button of a row.": "Berkas, folder, atau aplikasi yang dikecualikan dilewati oleh alat yang Anda pilih, dan tidak ada yang dihapus di folder yang dikecualikan. Kecualikan dari hasil pindai dengan tombol Kecualikan pada sebuah baris.",
