"AppCleaner can clear the caches that no file access can reach (the \"Clear cache\" button of an app's Storage screen) by tapping through the system settings for you. For that it needs this app's accessibility service. The service only acts while AppCleaner is clearing caches: it opens the App info screen of one app after the other, taps Clear cache, and stops when the screen turns off or locks. A cover over the screen shows what it is doing, with a way to cancel. Nothing is read or sent anywhere. On Android 13 and newer, an app installed from a file may first need \"Allow restricted settings\" (App info of this app, the three dots menu).": "AppCleaner dapat menghapus cache yang tidak terjangkau akses berkas apa pun (tombol “Hapus cache” pada layar Penyimpanan aplikasi) dengan mengetuk pengaturan sistem untuk Anda. Untuk itu, ia membutuhkan layanan aksesibilitas aplikasi ini. Layanan hanya bekerja saat AppCleaner menghapus cache: membuka layar Info aplikasi satu per satu, mengetuk Hapus cache, dan berhenti saat layar mati atau terkunci. Penutup di layar menunjukkan apa yang sedang dilakukan, dengan cara untuk membatalkan. Tidak ada yang dibaca atau dikirim ke mana pun. Pada Android 13 dan yang lebih baru, aplikasi yang dipasang dari berkas mungkin perlu “Izinkan pengaturan terbatas” terlebih dahulu (Info aplikasi dari aplikasi ini, menu tiga titik).",
