"Browser Use": "Browser Use",
"Browser Use did not start the task.": "Browser Use tidak memulai tugas.",
"Browser Use failed before it had an answer.": "Browser Use gagal sebelum mendapat jawaban.",
"Browser Use finished without an answer.": "Browser Use selesai tanpa jawaban.",
"Browser Use is the open-source browser agent; this is its hosted cloud, which has a free tier for new accounts. An Ask agent button starts a short browser task that looks the question up on the web: it can take a minute or two and uses a little credit. It is for the Ask agent buttons only, not a chat. Testing the key costs nothing.": "Browser Use adalah agen peramban sumber terbuka; ini adalah cloud-nya, yang punya tingkat gratis untuk akun baru. Tombol Ask agent memulai tugas peramban singkat yang mencari pertanyaan di web: bisa memakan satu atau dua menit dan memakai sedikit kredit. Hanya untuk tombol Ask agent, bukan obrolan. Menguji kunci tidak dikenai biaya.",
"Browser Use took too long (over 4 minutes). Try again later.": "Browser Use terlalu lama (lebih dari 4 menit). Coba lagi nanti.",
"Browser Use was stopped before it had an answer.": "Browser Use dihentikan sebelum mendapat jawaban.",
"Browser automation. Needs Node and a Chromium download, which can be heavy on a phone.": "Otomatisasi browser. Memerlukan Node dan unduhan Chromium, yang bisa berat di ponsel.",
