"Crawl4AI": "Crawl4AI",
"Crawl4AI found no answer for this one. Try Web search, or another agent.": "Crawl4AI tidak menemukan jawaban untuk ini. Coba Web search atau agen lain.",
"Crawl4AI is the open-source web crawler; this is its hosted cloud. A new account gets free credits and a free monthly allowance, no card. An Ask agent button sends the question to its answer service, which searches the web, reads the pages and writes the answer. It is for the Ask agent buttons only, not a chat. The test spends one credit.": "Crawl4AI adalah perayap web sumber terbuka; ini adalah cloud-nya. Akun baru mendapat kredit gratis dan jatah bulanan gratis, tanpa kartu. Tombol Ask agent mengirim pertanyaan ke layanan jawabannya, yang mencari di web, membaca halaman, dan menulis jawaban. Hanya untuk tombol Ask agent, bukan obrolan. Pengujian memakai satu kredit.",
