"Each agent keeps this in its own file, the same way its official sign-in does, so two or more agents can carry the same server and either can be used with it. Codex keeps a remote server's token as an environment variable instead of in its file. Not tested against every version of every tool.": "Setiap agen menyimpan ini di file-nya sendiri, seperti halnya login resminya, sehingga dua agen atau lebih dapat memiliki server yang sama dan keduanya dapat memakainya. Codex menyimpan token server jarak jauh sebagai variabel lingkungan, bukan di file-nya. Belum diuji pada setiap versi dari setiap alat.",
"Each part between dots can be 63 characters at most.": "Setiap bagian di antara titik paling banyak 63 karakter.",
"Each part between dots needs at least one character.": "Setiap bagian di antara titik harus punya setidaknya satu karakter.",
"Each shell keeps its own screen and stays open while you use other tabs: cd, export and variables carry over from one command to the next. Restart shell starts a fresh one.": "Setiap shell punya layarnya sendiri dan tetap terbuka saat Anda memakai tab lain: cd, export, dan variabel terbawa dari satu perintah ke perintah berikutnya. Mulai ulang shell memulai shell yang baru.",
"Each wait is 600 seconds (10 minutes) at most.": "Setiap tunggu paling lama 600 detik (10 menit).",
"Earlier certificates (the signing key was changed)": "Sertifikat sebelumnya (kunci penandatanganan telah diganti)",
