"Edit text": "Edit teks",
"Edited": "Diedit",
"Editing an APK changes its contents, so its signature no longer matches. Android will not install it until it is signed again: use Sign (this app signs with a key of its own).": "Mengedit APK mengubah isinya, sehingga tanda tangannya tidak lagi cocok. Android tidak akan menginstalnya sampai ditandatangani ulang: gunakan Tandatangani (aplikasi ini menandatangani dengan kunci miliknya sendiri).",
"Editing an APK changes its contents, so its signature no longer matches. Android will not install it until it is signed again; Sign does that with a key of this app.": "Mengedit APK mengubah isinya, sehingga tanda tangannya tidak lagi cocok. Android tidak akan menginstalnya sampai ditandatangani ulang; Tandatangani melakukannya dengan kunci aplikasi ini.",
"Effort": "Upaya",
"Effort only changes anything for the agents whose own API has that knob (Claude, ChatGPT, Gemini, Grok); for the others it is kept but has no effect when chatting by API key, and none of them pass it on to their own sign-in tool in Termux.": "Upaya hanya berpengaruh pada agen yang API-nya memiliki pengaturan itu (Claude, ChatGPT, Gemini, Grok); untuk yang lain nilainya tetap disimpan tetapi tidak berpengaruh saat chat dengan kunci API, dan tidak satu pun meneruskannya ke alat login mereka sendiri di Termux.",
"Emergency tone": "Nada darurat",
"Empty": "Kosong",
"Empty folder.": "Folder kosong.",
