"Exa": "Exa",
"Exa found no answer for this one. Try Web search, or another agent.": "Exa tidak menemukan jawaban untuk pertanyaan ini. Coba Pencarian web atau agen lain.",
"Exa is a search engine built for AI. Its answer service searches the web and writes a short answer that names its sources. A new account gets free credits. Testing the key makes one small search (a fraction of a cent). An Ask agent button sends it the question; nothing is sent until you press one.": "Exa adalah mesin pencari yang dibuat untuk AI. Layanan jawabannya menelusuri web dan menulis jawaban singkat dengan menyebutkan sumbernya. Akun baru mendapat kredit gratis. Menguji kunci hanya melakukan satu pencarian kecil (sepersekian sen). Tombol Tanya agen mengirimkan pertanyaan ke sana; tidak ada yang dikirim sampai Anda menekannya.",
