"Freeform windows (developer option)": "Jendela freeform (opsi pengembang)",
"Frees only the file page cache; Android fills it again as apps read files.": "Hanya membebaskan cache halaman file; Android mengisinya lagi saat aplikasi membaca file.",
"Frees only the page cache (copies of files the kernel keeps in RAM so they open faster). Apps are not touched. Android fills it again as apps read files.": "Hanya membebaskan cache halaman (salinan file yang disimpan kernel di RAM agar lebih cepat dibuka). Aplikasi tidak disentuh. Android mengisinya lagi saat aplikasi membaca file.",
