"Gemini, Claude, ChatGPT, Cursor, Perplexity, Grok, Muse and Deepseek connect with an API key from the provider's website (links below). Usage is billed by the provider to that key's account; Google's Gemini API also has a free tier, where Google may use what you send to improve its products.": "Gemini, Claude, ChatGPT, Cursor, Perplexity, Grok, Muse, dan Deepseek terhubung dengan kunci API dari situs web penyedianya (tautan di bawah). Penggunaan ditagihkan oleh penyedia ke akun pemilik kunci tersebut; Gemini API dari Google juga memiliki tingkat gratis, yang datanya dapat digunakan Google untuk meningkatkan produknya.",
