"Jan runs AI models on your computer, free. On the computer: Jan, Settings, Local API Server: set the host to 0.0.0.0 and start it, then enter the computer's address here (like http://192.168.1.20:1337/v1). There is no Android version of Jan.": "Jan menjalankan model AI di komputer Anda, gratis. Di komputer: Jan, Settings, Local API Server: atur host ke 0.0.0.0 lalu jalankan servernya, kemudian masukkan alamat komputer di sini (misalnya http://192.168.1.20:1337/v1). Jan tidak punya versi Android.",
