"Not for this version": "Bukan untuk versi ini",
"Not found on USB. Check the cable, unlock the device and make sure USB debugging is on, then try again.": "Tidak ditemukan di USB. Periksa kabel, buka kunci perangkat, dan pastikan debugging USB aktif, lalu coba lagi.",
"Not found on this phone. Enter the address of the computer that runs it, then Connect.": "Tidak ditemukan di ponsel ini. Masukkan alamat komputer yang menjalankannya, lalu ketuk Hubungkan.",
"Not found: the model may not exist or may not be open to this key. Pick another model.": "Tidak ditemukan: model itu mungkin tidak ada atau tidak tersedia untuk kunci ini. Pilih model lain.",
"Not frozen": "Tidak dibekukan",
"Not granted": "Tidak diberikan",
"Not in the list? Search the whole catalog for": "Tidak ada di daftar? Cari seluruh katalog untuk",
"Not in use: the theme above is a curated palette. Choose a style to build one from the source color.": "Tidak digunakan: tema di atas adalah palet pilihan. Pilih gaya untuk membuatnya dari warna sumber.",
"Not installed": "Tidak terpasang",
