"Not stated": "Tidak dinyatakan",
"Not supported": "Tidak didukung",
"Not tested": "Belum diuji",
"Nothing but your message is added.": "Tidak ada yang ditambahkan selain pesan Anda.",
"Nothing changes until you tap Apply. The card reads the three scales back and shows what the phone really holds.": "Tidak ada yang berubah sampai kamu mengetuk Terapkan. Kartu membaca ulang ketiga skala dan menunjukkan apa yang benar-benar ada di ponsel.",
"Nothing changes until you tap Apply. The card reads the value back and shows what the phone really holds.": "Tidak ada yang berubah sampai kamu mengetuk Terapkan. Kartu membaca ulang nilainya dan menunjukkan apa yang benar-benar ada di ponsel.",
"Nothing changes until you tap a service. The card reads the phone back and shows what it really holds.": "Tidak ada yang berubah sampai Anda mengetuk sebuah layanan. Kartu membaca ulang ponsel dan menunjukkan isinya yang sebenarnya.",
"Nothing chosen yet.": "Belum ada yang dipilih.",
"Nothing found.": "Tidak ditemukan.",
"Nothing found. Both devices must be on the same Wi-Fi network, with wireless debugging on. You can also type the address by hand under Wi-Fi.": "Tidak ditemukan apa pun. Kedua perangkat harus berada di jaringan Wi-Fi yang sama, dengan debugging nirkabel aktif. Anda juga dapat mengetik alamat secara manual di bawah Wi-Fi.",
"Nothing found. Keep the Wireless Debugging screen open and enter the ports manually.": "Tidak ditemukan apa pun. Biarkan layar Debugging nirkabel tetap terbuka dan masukkan port secara manual.",
"Nothing happened within 10 seconds, although the command reported no error: the mode could not do it.": "Tidak terjadi apa-apa dalam 10 detik, meskipun perintah tidak melaporkan kesalahan: mode ini tidak bisa melakukannya.",
"Nothing happened within 10 seconds: the mode could not do it.": "Tidak terjadi apa-apa dalam 10 detik: mode ini tidak bisa melakukannya.",
"Nothing here was changed with this app yet.": "Belum ada yang diubah di sini dengan aplikasi ini.",
"Nothing here was tested on every phone: when a step fails, the Terminal shows the exact error.": "Tidak ada bagian di sini yang sudah diuji di semua ponsel: jika suatu langkah gagal, Terminal menampilkan error persisnya.",
"Nothing in the guide matches that. Try fewer or different words.": "Tidak ada isi panduan yang cocok. Coba kata yang lebih sedikit atau berbeda.",
"Nothing inside.": "Tidak ada isinya.",
"Nothing is selected": "Tidak ada yang dipilih",
"Nothing is swapped out right now.": "Saat ini tidak ada yang dipindahkan ke swap.",
"Nothing matched. Try the package name, for example com.example.app.": "Tidak ada yang cocok. Coba nama paket, misalnya com.example.app.",
"Nothing matches that filter.": "Tidak ada yang cocok dengan filter itu.",
