"Nothing runs until you confirm in the sheet. Power off, Bootloader and Recovery ask for a press-and-hold there.": "Tidak ada yang berjalan sampai Anda mengonfirmasi di lembar. Matikan, Bootloader, dan Recovery meminta tekan-dan-tahan di sana.",
"Nothing runs until you confirm. After every action the section reads the phase back from the phone and shows that, not the command.": "Tidak ada yang berjalan sampai Anda mengonfirmasi. Setelah setiap tindakan, bagian ini membaca kembali fase dari ponsel dan menampilkannya, bukan perintahnya.",
