"Nothing to revoke here": "Tidak ada yang perlu dicabut di sini",
"Nothing to run again": "Tidak ada yang perlu dijalankan ulang",
"Nothing to save: refresh the log first": "Tidak ada yang bisa disimpan: segarkan log terlebih dahulu",
"Nothing to set here.": "Tidak ada yang perlu diatur di sini.",
"Nothing to share": "Tidak ada yang bisa dibagikan",
