"Nothing was changed with this app yet": "Belum ada yang diubah dengan aplikasi ini",
"Nothing was changed with this app yet.": "Belum ada yang diubah dengan aplikasi ini.",
"Nothing was recorded": "Tidak ada yang direkam",
"Nothing was saved.": "Tidak ada yang disimpan.",
"Nothing was sent: one of the numbers is not a speed.": "Tidak ada yang dikirim: salah satu angka bukan kecepatan.",
"Nothing was sent: the number is not a bias between −1 and 1.": "Tidak ada yang dikirim: angkanya bukan geseran antara −1 dan 1.",
"Notification": "Notifikasi",
