"Pick an agent, then the model and the effort (Low, Balanced or High: how hard it is asked to think). The first time, both start at a balanced choice, and the agent asks for what it needs (an API key, a server address, or a sign-in) and tests it before you start.": "Pilih agen, lalu model dan upaya (Rendah, Seimbang, atau Tinggi: seberapa keras agen diminta berpikir). Pada awalnya, keduanya dimulai dengan pilihan seimbang, dan agen meminta apa yang dibutuhkannya (kunci API, alamat server, atau login) lalu mengujinya sebelum Anda mulai.",
