"Puts the phone into deep Doze now, as if it had lain still for an hour: background work and network pause for most apps.": "Memasukkan ponsel ke Doze dalam sekarang, seolah sudah diam selama satu jam: kerja latar belakang dan jaringan berhenti sejenak untuk sebagian besar aplikasi.",
"Puts the phone into deep Doze right now, as if it had lain still for an hour: for most apps background work, network and alarms wait until the next maintenance window. The phone still rings. The forced Doze stays until you tap Wake device or the phone restarts.": "Memasukkan ponsel ke Doze dalam seketika, seolah sudah diam selama satu jam: bagi sebagian besar aplikasi, kerja latar belakang, jaringan, dan alarm menunggu jendela pemeliharaan berikutnya. Ponsel tetap berdering. Doze paksa bertahan sampai Anda mengetuk Bangunkan perangkat atau ponsel dimulai ulang.",
