"Tip:": "Tips:",
"To browse files on this phone, this app needs All-files access (or a working mode: ADB, Shizuku or Root).": "Untuk menjelajahi file di ponsel ini, aplikasi ini memerlukan Akses semua file (atau mode kerja: ADB, Shizuku, atau Root).",
"To get an explanation, choose a Default Ask Agent and connect it.": "Untuk mendapatkan penjelasan, pilih Agen Tanya Bawaan dan hubungkan.",
"To look in Downloads this app needs": "Untuk mencari di Unduhan, aplikasi ini memerlukan",
"To make this the default installer, open any APK, choose this app, and tap \"Always\".": "Untuk menjadikan ini penginstal default, buka APK apa pun, pilih aplikasi ini, lalu ketuk “Selalu”.",
"To search storage for APK, APKS, APKM and XAPK files, this app needs All-files access (or a working mode: ADB, Shizuku or Root).": "Untuk mencari file APK, APKS, APKM, dan XAPK di penyimpanan, aplikasi ini memerlukan Akses semua file (atau mode kerja: ADB, Shizuku, atau Root).",
"To search storage for fonts, this app needs All-files access. You can also choose a font file by hand, which needs no access.": "Untuk mencari font di penyimpanan, aplikasi ini memerlukan akses ke semua file. Anda juga dapat memilih file font secara manual tanpa akses apa pun.",
"To search storage, this app needs": "Untuk mencari di penyimpanan, aplikasi ini memerlukan",
"To search the files on this phone, this app needs All-files access.": "Untuk mencari file di ponsel ini, aplikasi memerlukan akses Semua file.",
"To use DroidMind with an agent that speaks MCP (such as Claude Code or OpenCode), install it into the Debian container in Termux. Then start it with droidmind --transport sse and add it to that agent as an MCP server.": "Untuk memakai DroidMind dengan agen yang mendukung MCP (seperti Claude Code atau OpenCode), instal DroidMind ke kontainer Debian di Termux. Lalu jalankan dengan droidmind --transport sse dan tambahkan ke agen itu sebagai server MCP.",
