"Turn Wi-Fi off": "Matikan Wi-Fi",
"Turn Wi-Fi on": "Nyalakan Wi-Fi",
"Turn a tab off to take it out of the tab bar and use the arrows to put the tabs in the order you like. Application Manager and About always stay where they are.": "Nonaktifkan tab untuk mengeluarkannya dari bilah tab, dan gunakan panah untuk mengatur urutan tab sesuai keinginan. Manajer Aplikasi dan Tentang selalu tetap di tempatnya.",
"Turn mobile data off": "Matikan data seluler",
"Turn mobile data on": "Nyalakan data seluler",
"Turn off": "Matikan",
"Turn on": "Aktifkan",
"Turn on usage access for ADB/Root Full System Toolbox, then come back": "Aktifkan akses penggunaan untuk ADB/Root Full System Toolbox, lalu kembali",
"Turned off: a dropped device waits for Reconnect.": "Mati: perangkat yang terputus menunggu Hubungkan ulang.",
"Turning ANGLE off needs Root mode": "Menonaktifkan ANGLE perlu mode Root",
"Turning off ANGLE…": "Menonaktifkan ANGLE…",
"Turning on ANGLE…": "Mengaktifkan ANGLE…",
"Turns battery saver off and asks Android for its fixed performance mode: the CPU and GPU hold a steady clock instead of ramping up and down, which gives even frame times and uses more battery and heat. Android 11 or newer.": "Mematikan penghemat baterai dan meminta Android mengaktifkan mode performa tetap: CPU dan GPU mempertahankan clock stabil alih-alih naik turun, yang memberi waktu bingkai merata dan lebih boros baterai serta panas. Android 11 atau lebih baru.",
"Turns battery saver off and, where the phone has it, adaptive battery saver on (Android turns the saver on by itself when the battery runs low). The phone's normal state.": "Mematikan penghemat baterai dan, jika ponsel memilikinya, mengaktifkan penghemat baterai adaptif (Android menyalakan penghemat sendiri saat baterai hampir habis). Keadaan normal ponsel.",
"Tweaks and controls that Android hides": "Pengaturan dan kontrol yang disembunyikan Android",
"Two-button navigation bar": "Bilah navigasi dua tombol",
"Type": "Jenis",
"Type a command": "Ketik perintah",
"Type a command first": "Ketik perintah terlebih dahulu",
"Type a command for the device and press Run. A line that starts with \"adb \" goes to adb itself (adb pull, adb forward ...).": "Ketik perintah untuk perangkat lalu tekan Jalankan. Baris yang diawali “adb ” dikirim ke adb itu sendiri (adb pull, adb forward ...).",
"Type a command for the device and press Run. Start a line with \"adb \" to send it to adb itself (adb pull, adb forward ...). The $ button switches to adb for every line.": "Ketik perintah untuk perangkat lalu tekan Jalankan. Awali baris dengan “adb ” untuk mengirimnya ke adb itu sendiri (adb pull, adb forward ...). Tombol $ beralih ke adb untuk setiap baris.",
"Type a host name first.": "Ketik nama host terlebih dahulu.",
"Type a number between −1 and 1, like −0.3 or 0.5.": "Ketik angka antara −1 dan 1, seperti −0,3 atau 0,5.",
"Type a number of 0 or more, like 0.5 or 1.": "Ketik angka 0 atau lebih, seperti 0,5 atau 1.",
"Type a whole number, like 280": "Ketik bilangan bulat, seperti 280",
"Type an app name or package name.": "Ketik nama aplikasi atau nama paket.",
"Type in the search box to find a word anywhere in the guide. This guide is in English.": "Ketik di kotak pencarian untuk menemukan kata di mana saja dalam panduan. Panduan ini dalam bahasa Inggris.",
