"What the phone is doing right now: memory, storage and battery, with the model and software underneath. Reads only, nothing changes.": "Apa yang sedang dilakukan ponsel sekarang: memori, penyimpanan, dan baterai, dengan model dan perangkat lunak di bawahnya. Hanya membaca, tidak ada yang berubah.",
