"What this tab does when a device you were connected to drops (Wi-Fi, Wireless debugging and Bluetooth devices; a cable is never retried on its own)": "Yang dilakukan tab ini saat perangkat yang tadinya terhubung terputus (perangkat Wi-Fi, Debugging nirkabel, dan Bluetooth; kabel tidak pernah dicoba ulang sendiri)",
