"When a Wi-Fi sign-in page is found (0 ignore, 1 ask, 2 avoid the network)": "Saat halaman login Wi-Fi ditemukan (0 abaikan, 1 tanya, 2 hindari jaringan)",
"When deleting duplicates, SD Maid decides which file to keep by checking each criterion in order. The first criterion that produces a clear winner determines the result. Drag to reorder, tap to change mode.": "Saat menghapus duplikat, SD Maid menentukan berkas yang dipertahankan dengan memeriksa tiap kriteria secara berurutan. Kriteria pertama yang menghasilkan pemenang jelas menentukan hasilnya. Seret untuk mengurutkan ulang, ketuk untuk mengubah mode.",
"When the chosen source does not have the version or does not work, This version, Newest and All versions go on with the next source, in the order above, until one delivers.": "Saat sumber terpilih tidak memiliki versinya atau tidak berfungsi, Versi ini, Terbaru, dan Semua versi lanjut ke sumber berikutnya, sesuai urutan di atas, sampai ada yang berhasil.",
"Where the tabs are. The bottom bar holds the tabs you pin and a More button for the rest; the top bar holds all of them.": "Letak tab. Bilah bawah memuat tab yang Anda sematkan dan tombol Lainnya untuk sisanya; bilah atas memuat semuanya.",
