"Whoever gets this file can sign apps as you, and Android will install them as updates of the apps you patched here. Send it only to a place that only you can open.": "Siapa pun yang menerima file ini dapat menandatangani aplikasi atas nama Anda, dan Android akan memasangnya sebagai pembaruan aplikasi yang Anda patch di sini. Kirim hanya ke tempat yang hanya bisa Anda buka.",
