"Writes everything that is waiting to be written, then tells the kernel to free the page cache and the folder and inode caches. Apps are not touched. The phone may feel slower for a moment while the caches fill again; the freed RAM is mostly a short-lived gain.": "Menulis semua yang menunggu ditulis, lalu meminta kernel membebaskan cache halaman serta cache folder dan inode. Aplikasi tidak disentuh. Ponsel mungkin terasa lebih lambat sesaat selagi cache terisi lagi; RAM yang dibebaskan kebanyakan hanya keuntungan sesaat.",
"Writes pending data, then frees the file, folder and inode caches.": "Menulis data tertunda, lalu membebaskan cache file, folder, dan inode.",
"Written into Android as a color overlay, which only Root can do. Apply writes it along with the theme.": "Ditulis ke Android sebagai overlay warna, yang hanya bisa dilakukan Root. Terapkan menulisnya bersama tema.",
