"You can grant or revoke it here.": "Anda dapat memberikan atau mencabutnya di sini.",
"You edited this APK, so its signature is no longer valid and Android will not install it as it is.": "Anda mengedit APK ini, sehingga tanda tangannya tidak lagi valid dan Android tidak akan menginstalnya apa adanya.",
"You explain one Android hidden setting (an entry of the Settings.Global, Settings.Secure or Settings.System database, the ones \"settings get/put\" reads and writes) to someone who is not a developer.": "Anda menjelaskan satu pengaturan tersembunyi Android (entri basis data Settings.Global, Settings.Secure, atau Settings.System, yang dibaca dan ditulis oleh “settings get/put”) kepada orang yang bukan pengembang.",
"You explain one Android hidden setting (an entry of the Settings.Global, Settings.Secure or Settings.System database, the ones \"settings get/put\" reads and writes) to someone who is not a developer. Say briefly: what it controls, what its values mean, what changing it does, and whether it is safe to change. Say plainly when you do not know the setting (many belong to the phone maker) instead of guessing, and then say what its name suggests. Short paragraphs, no headings.": "Anda menjelaskan satu pengaturan tersembunyi Android (entri basis data Settings.Global, Settings.Secure, atau Settings.System, yang dibaca dan ditulis oleh “settings get/put”) kepada orang yang bukan pengembang. Jelaskan singkat: apa yang dikendalikannya, apa arti nilainya, apa yang terjadi bila diubah, dan apakah aman diubah. Katakan dengan jelas jika Anda tidak mengenal pengaturannya (banyak yang milik pabrikan ponsel) alih-alih menebak, lalu katakan apa yang disarankan namanya. Paragraf pendek, tanpa judul.",
"You explain one Android logcat entry to someone who is not a developer. Say, in plain words and briefly: what this line means,": "Anda menjelaskan satu entri logcat Android kepada orang yang bukan pengembang. Jelaskan dengan kata-kata sederhana dan singkat: apa arti baris ini,",
"You explain one Android logcat entry to someone who is not a developer. Say, in plain words and briefly: what this line means, the most likely cause, whether it matters (harmless noise, a real problem, or a crash) and, if it does matter, what to try. Use short paragraphs, no headings. If the line is too cryptic to explain with confidence, say so and say what else would help. Do not invent details.": "Anda menjelaskan satu entri logcat Android kepada orang yang bukan pengembang. Jelaskan dengan kata-kata sederhana dan singkat: apa arti baris ini, penyebab yang paling mungkin, apakah penting (noise tak berbahaya, masalah nyata, atau crash) dan, jika penting, apa yang bisa dicoba. Gunakan paragraf pendek, tanpa judul. Jika baris terlalu samar untuk dijelaskan dengan yakin, katakan begitu dan katakan apa lagi yang akan membantu. Jangan mengarang detail.",
"You help with ADB and shell command syntax in an Android terminal. Answer briefly and practically.": "Anda membantu dengan sintaks perintah ADB dan shell di terminal Android. Jawab dengan singkat dan praktis.",
"You help with ADB and shell command syntax in an Android terminal. Answer briefly and practically. If you want to propose exactly one command for the user to run here, put it by itself inside": "Anda membantu dengan sintaks perintah ADB dan shell di terminal Android. Jawab dengan singkat dan praktis. Jika Anda ingin mengusulkan tepat satu perintah untuk dijalankan pengguna di sini, letakkan sendiri di dalam",
"You're on a metered connection (mobile data / hotspot).": "Anda menggunakan koneksi berkuota (data seluler / hotspot).",
"Your color": "Warna Anda",
"Your email app is open: tap send there": "Aplikasi email Anda terbuka: ketuk kirim di sana",
"Your host name": "Nama host Anda",
"Your message": "Pesan Anda",
"Your own number": "Nomor Anda sendiri",
"Your phone first looks up each service’s name with the DNS it uses now (once). Then each service may receive up to three short encrypted connections, each asking for example.com. ICMP ping is not available to apps, so the times are for the encrypted connection Private DNS actually uses.": "Ponsel Anda lebih dulu mencari nama setiap layanan dengan DNS yang sedang dipakai (sekali). Lalu setiap layanan bisa menerima hingga tiga koneksi terenkripsi singkat, masing-masing menanyakan example.com. Ping ICMP tidak tersedia untuk aplikasi, jadi waktunya untuk koneksi terenkripsi yang benar-benar dipakai DNS pribadi.",
"Your phone was updated.": "Ponsel Anda telah diperbarui.",
"Your root manager was not found by its usual name (it may be installed under a different name). If it lists an app only after the app has asked for su, tap Request Super User first and allow this app when it asks. Otherwise open it yourself, allow this app, then tap Request Super User.": "Pengelola root Anda tidak ditemukan dengan namanya yang biasa (mungkin terpasang dengan nama lain). Jika pengelola itu hanya menampilkan aplikasi setelah aplikasi meminta su, ketuk “Minta Superuser” terlebih dahulu dan izinkan aplikasi ini saat ditanya. Jika tidak, buka sendiri, izinkan aplikasi ini, lalu ketuk “Minta Superuser”.",
"Your root manager was not found by its usual name (it may be hidden or renamed). Open it from your home screen and manage apps in its Super User list.": "Pengelola root Anda tidak ditemukan dengan namanya yang biasa (mungkin disembunyikan atau diganti namanya). Buka dari layar utama dan kelola aplikasi di daftar Super User-nya.",
"Yours stay. A list that is already here is skipped; one with the same name but other apps comes in as \"Name (imported)\".": "Milik Anda tetap ada. Daftar yang sudah ada dilewati; daftar dengan nama sama tetapi aplikasi lain masuk sebagai “Nama (diimpor)”.",
